export { chainFocus, isValidUrl } from "./commands";
export { extensionPresent, nodeActive } from "./detection";
export { shallowEqual, useEditorState } from "./editor-state";
export { DEFAULT_EXTENSION_LABELS } from "./labels";
export type { ExtensionLabelKey, ExtensionLabels } from "./labels";
export { ToolbarProvider, useToolbar, useToolbarEditor } from "./context";
export type { ToolbarContextValue, ToolbarProviderProps } from "./context";
export type { ToolbarComponentProps } from "./types";

import type { ChainedCommands, Editor } from "@tiptap/core";

export const chainFocus = (editor: Editor): ChainedCommands =>
  editor.chain().focus();

export const isValidUrl = (url: string): boolean =>
  /^https?:\/\/\S+$/.test(url);

import type { Editor } from "@tiptap/core";
import type { ReactNode } from "react";
import { createContext, useContext, useMemo } from "react";

import type { ExtensionLabels } from "./labels";
import { DEFAULT_EXTENSION_LABELS } from "./labels";

export interface ToolbarContextValue {
  editor: Editor | null;
  labels: ExtensionLabels;
}

const ToolbarContext = createContext<ToolbarContextValue>({
  editor: null,
  labels: DEFAULT_EXTENSION_LABELS,
});

export interface ToolbarProviderProps {
  children: ReactNode;
  editor?: Editor | null;
  labels?: Partial<ExtensionLabels>;
}

export const ToolbarProvider = ({
  children,
  editor = null,
  labels,
}: ToolbarProviderProps) => {
  const value = useMemo(
    () => ({
      editor,
      labels: { ...DEFAULT_EXTENSION_LABELS, ...labels },
    }),
    [editor, labels]
  );

  return (
    <ToolbarContext.Provider value={value}>{children}</ToolbarContext.Provider>
  );
};

export const useToolbar = (): ToolbarContextValue => useContext(ToolbarContext);

export const useToolbarEditor = (
  editor: Editor | null | undefined
): Editor | null => {
  const context = useContext(ToolbarContext);
  return editor ?? context.editor ?? null;
};

import type { Editor } from "@tiptap/core";

export const extensionPresent = (
  editor: Editor | null,
  name: string
): boolean =>
  Boolean(
    editor &&
    !editor.isDestroyed &&
    editor.extensionManager.extensions.some(
      (extension) => extension.name === name
    )
  );

export const nodeActive = (
  editor: Editor | null,
  name: string,
  attributes?: Record<string, unknown>
): boolean =>
  Boolean(editor && !editor.isDestroyed && editor.isActive(name, attributes));

import type { Editor } from "@tiptap/core";
import { useCallback, useRef, useSyncExternalStore } from "react";

const defaultEqual = <T>(a: T, b: T): boolean => a === b;

export const shallowEqual = <T extends Record<string, unknown>>(
  a: T,
  b: T
): boolean => {
  if (a === b) {
    return true;
  }
  if (!a || !b) {
    return false;
  }
  const ak = Object.keys(a);
  const bk = Object.keys(b);
  if (ak.length !== bk.length) {
    return false;
  }
  return ak.every((k) => a[k] === b[k]);
};

const isPlainEmpty = <T>(value: T | undefined): value is undefined =>
  value === undefined;

export const useEditorState = <T>(
  editor: Editor | null,
  selector: (e: Editor) => T,
  isEqual: (a: T, b: T) => boolean = defaultEqual
): T | undefined => {
  const selectorRef = useRef(selector);
  const isEqualRef = useRef(isEqual);
  selectorRef.current = selector;
  isEqualRef.current = isEqual;

  const snapshotRef = useRef<{ value: T | undefined }>({
    value: editor ? selector(editor) : undefined,
  });

  const computeSnapshot = useCallback((): T | undefined => {
    if (!editor) {
      return undefined;
    }
    const next = selectorRef.current(editor);
    const current = snapshotRef.current.value;
    if (isPlainEmpty(current) || !isEqualRef.current(current, next)) {
      snapshotRef.current.value = next;
    }
    return snapshotRef.current.value;
  }, [editor]);

  const subscribe = useCallback(
    (onStoreChange: () => void) => {
      if (!editor) {
        return () => {
          /* Nothing to subscribe to. */
        };
      }
      const update = () => {
        computeSnapshot();
        onStoreChange();
      };
      editor.on("selectionUpdate", update);
      editor.on("transaction", update);
      return () => {
        editor.off("selectionUpdate", update);
        editor.off("transaction", update);
      };
    },
    [editor, computeSnapshot]
  );

  return useSyncExternalStore(subscribe, computeSnapshot, computeSnapshot);
};

export interface ExtensionLabels {
  addColumnLeft: string;
  addColumnRight: string;
  addRowAbove: string;
  addRowBelow: string;
  columnActions: string;
  columns: string;
  deleteColumn: string;
  deleteRow: string;
  deleteTable: string;
  headerRow: string;
  image: string;
  imagePlaceholder: string;
  insertTable: string;
  mergeCells: string;
  rowActions: string;
  rows: string;
  splitCell: string;
  tableActions: string;
}

export type ExtensionLabelKey = keyof ExtensionLabels;

export const DEFAULT_EXTENSION_LABELS: ExtensionLabels = {
  addColumnLeft: "Insert Left",
  addColumnRight: "Insert Right",
  addRowAbove: "Insert Above",
  addRowBelow: "Insert Below",
  columnActions: "Column actions",
  columns: "Columns",
  deleteColumn: "Delete column",
  deleteRow: "Delete row",
  deleteTable: "Delete table",
  headerRow: "Header row",
  image: "Image",
  imagePlaceholder: "Add an image",
  insertTable: "Insert table",
  mergeCells: "Merge cells",
  rowActions: "Row actions",
  rows: "Rows",
  splitCell: "Split cell",
  tableActions: "Table actions",
};

import type { Editor } from "@tiptap/core";

export interface ToolbarComponentProps {
  className?: string;
  editor?: Editor | null;
  size?: "icon" | "icon-lg" | "icon-sm";
}

import { Mention as TiptapMention } from "@tiptap/extension-mention";
import type { MentionOptions as TiptapMentionOptions } from "@tiptap/extension-mention";
import type { EditorState } from "@tiptap/pm/state";
import { PluginKey } from "@tiptap/pm/state";
import type { ReactNode } from "react";

import { renderMentionList } from "./mention-list";

export interface MentionItem {
  avatar?: string;
  description?: string;
  id: string;
  label: string;
}

export interface MentionOptions extends TiptapMentionOptions<MentionItem> {
  debounce: number;
  heading?: string;
  items: (query: string) => MentionItem[] | Promise<MentionItem[]>;
  renderItem?: (item: MentionItem) => ReactNode;
  trigger: string;
}

export const mentionPluginKey = new PluginKey("mention");

export const isMentionActive = (state: EditorState): boolean =>
  Boolean(mentionPluginKey.getState(state)?.active);

const mentionText = (attrs: Record<string, unknown>) =>
  `${attrs.mentionSuggestionChar ?? "@"}${attrs.label ?? attrs.id}`;

export const Mention = TiptapMention.extend<MentionOptions>({
  addOptions() {
    return {
      ...(this.parent?.() as TiptapMentionOptions<MentionItem>),
      debounce: 150,
      deleteTriggerWithBackspace: true,
      heading: undefined,
      items: () => [],
      renderHTML: ({ node, options }) => [
        "span",
        options.HTMLAttributes,
        mentionText(node.attrs),
      ],
      renderItem: undefined,
      renderText: ({ node }) => mentionText(node.attrs),
      trigger: "@",
    };
  },

  addProseMirrorPlugins() {
    const { debounce, heading, items, renderItem, suggestion, trigger } =
      this.options;
    this.options.suggestion = {
      char: trigger,
      debounce,
      items: ({ query }) => items(query),
      pluginKey: mentionPluginKey,
      render: () => renderMentionList({ heading, renderItem }),
      ...suggestion,
    };
    return this.parent?.() ?? [];
  },
});

"use client";

import { ReactRenderer } from "@tiptap/react";
import type {
  SuggestionKeyDownProps,
  SuggestionOptions,
  SuggestionProps,
} from "@tiptap/suggestion";
import {
  forwardRef,
  useImperativeHandle,
  useLayoutEffect,
  useRef,
  useState,
} from "react";
import type { ReactNode } from "react";

import { DropdownMenuContent } from "../ui/dropdown-content";
import { DropdownMenuItem } from "../ui/dropdown-item";
import type { MentionItem } from "./index";

interface MentionListOptions {
  heading?: string;
  renderItem?: (item: MentionItem) => ReactNode;
}

type MentionListProps = SuggestionProps<MentionItem, MentionItem> &
  MentionListOptions;

interface MentionListHandle {
  onKeyDown: (props: SuggestionKeyDownProps) => boolean;
}

const DefaultItem = ({ avatar, description, label }: MentionItem) => {
  const [failed, setFailed] = useState(false);
  return (
    <>
      {avatar && !failed ? (
        <img
          alt=""
          className="ext-mention-avatar"
          onError={() => setFailed(true)}
          src={avatar}
        />
      ) : (
        <span aria-hidden className="ext-mention-avatar">
          {label.charAt(0).toUpperCase()}
        </span>
      )}
      <span className="ext-mention-text">
        <span className="ext-mention-label">{label}</span>
        {description && (
          <span className="ext-mention-description">{description}</span>
        )}
      </span>
    </>
  );
};

const MentionList = forwardRef<MentionListHandle, MentionListProps>(
  ({ command, heading, items, loading, renderItem }, ref) => {
    const [selected, setSelected] = useState(0);
    const [activeItem, setActiveItem] = useState<HTMLElement | null>(null);
    const listRef = useRef<HTMLDivElement>(null);

    const [prevItems, setPrevItems] = useState(items);
    if (prevItems !== items) {
      setPrevItems(items);
      setSelected(0);
    }

    useLayoutEffect(() => {
      const item =
        listRef.current?.querySelectorAll<HTMLElement>("[data-dropdown-item]")[
          selected
        ] ?? null;
      setActiveItem(item);
      item?.scrollIntoView({ block: "nearest" });
    }, [items, selected]);

    const select = (index: number) => {
      const item = items[index];
      if (item) {
        command(item);
      }
    };

    useImperativeHandle(ref, () => ({
      onKeyDown: ({ event }) => {
        if (items.length === 0) {
          return false;
        }
        if (event.key === "ArrowUp") {
          setSelected((selected + items.length - 1) % items.length);
          return true;
        }
        if (event.key === "ArrowDown") {
          setSelected((selected + 1) % items.length);
          return true;
        }
        if (event.key === "Enter" || event.key === "Tab") {
          select(selected);
          return true;
        }
        return false;
      },
    }));

    return (
      <DropdownMenuContent
        activeItem={items.length > 0 ? activeItem : null}
        aria-busy={loading}
        className="ext-mention-list"
        ref={listRef}
        role="listbox"
      >
        {heading && <div className="ext-mention-heading">{heading}</div>}
        {items.length === 0 ? (
          <div className="ext-mention-empty">
            {loading ? "Searching…" : "No results"}
          </div>
        ) : (
          items.map((item, index) => (
            <DropdownMenuItem
              aria-selected={index === selected}
              key={item.id}
              onClick={() => select(index)}
              onMouseDown={(e) => e.preventDefault()}
              onMouseEnter={() => setSelected(index)}
              role="option"
            >
              {renderItem ? renderItem(item) : <DefaultItem {...item} />}
            </DropdownMenuItem>
          ))
        )}
      </DropdownMenuContent>
    );
  }
);

export const renderMentionList = (
  options: MentionListOptions
): ReturnType<NonNullable<SuggestionOptions<MentionItem>["render"]>> => {
  let component: ReactRenderer<MentionListHandle, MentionListProps> | null =
    null;
  let unmount: (() => void) | null = null;

  return {
    onExit: () => {
      unmount?.();
      component?.destroy();
      component = null;
      unmount = null;
    },
    onKeyDown: (props) => component?.ref?.onKeyDown(props) ?? false,
    onStart: (props) => {
      component = new ReactRenderer(MentionList, {
        editor: props.editor,
        props: { ...props, ...options },
      });
      unmount = props.mount(component.element as HTMLElement);
    },
    onUpdate: (props) => {
      component?.updateProps({ ...props, ...options });
    },
  };
};

import * as React from "react";
import { useCallback, useLayoutEffect, useState } from "react";

export interface DropdownPillHandlers {
  onFocus: (event: React.FocusEvent<HTMLDivElement>) => void;
  onMouseLeave: (event: React.MouseEvent<HTMLDivElement>) => void;
  onMouseOver: (event: React.MouseEvent<HTMLDivElement>) => void;
}

interface PillRect {
  height: number;
  left: number;
  top: number;
  width: number;
}

const measure = (item: HTMLElement): PillRect => ({
  height: item.offsetHeight,
  left: item.offsetLeft,
  top: item.offsetTop,
  width: item.offsetWidth,
});

const useDropdownPill = (
  onMouseLeave?: (event: React.MouseEvent<HTMLDivElement>) => void,
  activeItem?: HTMLElement | null
): { handlers: DropdownPillHandlers; pill: React.ReactNode } => {
  const [rect, setRect] = useState<PillRect | null>(null);

  useLayoutEffect(() => {
    if (activeItem) {
      setRect(measure(activeItem));
    }
  }, [activeItem]);

  const handleItemEnter = useCallback((target: EventTarget | null) => {
    const item = (target as HTMLElement).closest<HTMLElement>(
      "[data-dropdown-item]"
    );
    if (!item) {
      return;
    }
    setRect(measure(item));
  }, []);

  const handlers: DropdownPillHandlers = {
    onFocus: (event: React.FocusEvent<HTMLDivElement>) => {
      handleItemEnter(event.target);
    },
    onMouseLeave: (event: React.MouseEvent<HTMLDivElement>) => {
      setRect(activeItem ? measure(activeItem) : null);
      onMouseLeave?.(event);
    },
    onMouseOver: (event: React.MouseEvent<HTMLDivElement>) => {
      handleItemEnter(event.target);
    },
  };

  const pill = (
    <div
      aria-hidden="true"
      className={["ext-dropdown-pill", rect ? "ext-dropdown-pill--visible" : ""]
        .filter(Boolean)
        .join(" ")}
      style={
        rect
          ? {
              height: rect.height,
              left: rect.left,
              top: rect.top,
              width: rect.width,
            }
          : undefined
      }
    />
  );

  return { handlers, pill };
};

export { useDropdownPill };

import * as React from "react";

import { useDropdownPill } from "./dropdown-pill";

export interface DropdownMenuContentProps extends React.HTMLAttributes<HTMLDivElement> {
  activeItem?: HTMLElement | null;
}

const DropdownMenuContent = React.forwardRef<
  HTMLDivElement,
  DropdownMenuContentProps
>(({ activeItem, className = "", onMouseLeave, ...props }, ref) => {
  const { handlers, pill } = useDropdownPill(onMouseLeave, activeItem);

  return (
    <div
      ref={ref}
      role="menu"
      className={`ext-dropdown-content ${className}`.trim()}
      {...handlers}
      {...props}
    >
      {pill}
      {props.children}
    </div>
  );
});
DropdownMenuContent.displayName = "DropdownMenuContent";

export { DropdownMenuContent };

import * as React from "react";

export interface DropdownMenuItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  danger?: boolean;
}

const DropdownMenuItem = React.forwardRef<
  HTMLButtonElement,
  DropdownMenuItemProps
>(({ className = "", danger = false, type = "button", ...props }, ref) => {
  const cls = [
    "ext-dropdown-item",
    danger ? "ext-dropdown-item--danger" : "",
    className,
  ]
    .filter(Boolean)
    .join(" ");

  return (
    <button
      ref={ref}
      type={type}
      role="menuitem"
      data-dropdown-item
      className={cls}
      {...props}
    />
  );
});
DropdownMenuItem.displayName = "DropdownMenuItem";

export { DropdownMenuItem };

span[data-type="mention"] {
  padding: 0.0625rem 0.25rem;
  border-radius: calc(var(--radius) - 4px);
  background: color-mix(in srgb, var(--primary) 10%, transparent);
  color: var(--primary);
  font-weight: 500;
  white-space: nowrap;
  box-decoration-break: clone;
}

.ext-mention-list {
  z-index: 60;
  min-width: 14rem;
  max-width: 20rem;
  max-height: 18rem;
  overflow-y: auto;
}

.ext-mention-avatar {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  width: 2rem;
  height: 2rem;
  border-radius: 9999px;
  background: var(--muted);
  color: var(--muted-foreground);
  font-size: 0.75rem;
  font-weight: 600;
  object-fit: cover;
}

.ext-mention-heading {
  padding: 0.375rem 0.5rem 0.25rem;
  color: var(--muted-foreground);
  font-size: 0.75rem;
  font-weight: 500;
}

.ext-mention-text {
  display: flex;
  flex-direction: column;
  min-width: 0;
  line-height: 1.25;
}

.ext-mention-label {
  overflow: hidden;
  color: var(--popover-foreground);
  font-size: 0.875rem;
  font-weight: 500;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ext-mention-description {
  overflow: hidden;
  color: var(--muted-foreground);
  font-size: 0.75rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.ext-mention-empty {
  padding: 0.375rem 0.5rem;
  color: var(--muted-foreground);
  font-size: 0.8125rem;
}

/* Extensions UI primitives using shadcn CSS variables */

@keyframes ext-pop-in {
  from {
    opacity: 0;
    translate: 0 0.25rem;
    scale: 0.95;
  }
  to {
    opacity: 1;
    translate: 0 0;
    scale: 1;
  }
}

/* ── Button ── */
.ext-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: 0.375rem;
  height: 2rem;
  padding: 0 0.625rem;
  border: 1px solid transparent;
  border-radius: calc(var(--radius) - 2px);
  background: transparent;
  color: inherit;
  font-size: 0.8125rem;
  font-family: inherit;
  font-weight: 500;
  white-space: nowrap;
  cursor: pointer;
  outline: none;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    border-color 150ms ease-out,
    transform 100ms ease-out;
}

.ext-btn > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-btn--icon {
  width: 2rem;
  padding: 0;
}

.ext-btn--icon-sm {
  width: 1.75rem;
  padding: 0;
}

.ext-btn:hover {
  background: var(--accent);
  color: var(--accent-foreground);
}

.ext-btn:focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: -2px;
}

.ext-btn:active {
  transform: scale(0.96);
}

.ext-btn:disabled {
  pointer-events: none;
  opacity: 0.5;
}

.ext-btn--active {
  background: var(--accent);
  color: var(--accent-foreground);
}

.ext-btn--danger {
  color: var(--destructive, #ef4444);
}

.ext-btn--danger:hover {
  background: color-mix(in srgb, var(--destructive, #ef4444) 10%, transparent);
  color: var(--destructive, #ef4444);
}

/* ── Dropdown ── */
.ext-dropdown-content {
  position: relative;
  min-width: 10rem;
  padding: 0.25rem;
  background: var(--popover);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  color: var(--popover-foreground);
  animation: ext-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.ext-dropdown-item {
  position: relative;
  z-index: 1;
  display: flex;
  align-items: center;
  gap: 0.5rem;
  width: 100%;
  padding: 0.375rem 0.5rem;
  border: none;
  border-radius: calc(var(--radius) - 4px);
  background: transparent;
  color: var(--popover-foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background-color 100ms ease-out,
    color 100ms ease-out,
    transform 100ms ease-out;
}

.ext-dropdown-item > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-dropdown-pill {
  position: absolute;
  top: 0;
  left: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: calc(var(--radius) - 4px);
  background: color-mix(in srgb, var(--primary) 6%, transparent);
  opacity: 0;
  transition:
    top 220ms cubic-bezier(0.22, 1, 0.36, 1),
    left 220ms cubic-bezier(0.22, 1, 0.36, 1),
    width 220ms cubic-bezier(0.22, 1, 0.36, 1),
    height 220ms cubic-bezier(0.22, 1, 0.36, 1),
    opacity 150ms ease-out;
}

.ext-dropdown-pill--visible {
  opacity: 1;
}

.ext-dropdown-item:hover,
.ext-dropdown-item:focus-visible {
  color: var(--foreground);
  outline: none;
}

.ext-dropdown-item:active {
  transform: scale(0.98);
}

.ext-dropdown-item:disabled {
  pointer-events: none;
  opacity: 0.5;
}

.ext-dropdown-item--danger {
  color: var(--destructive, #ef4444);
}

.ext-dropdown-item--danger:hover,
.ext-dropdown-item--danger:focus-visible {
  background: color-mix(in srgb, var(--destructive, #ef4444) 10%, transparent);
  color: var(--destructive, #ef4444);
}

.ext-dropdown-separator {
  height: 1px;
  background: var(--border);
  margin: 0.25rem 0;
}

/* ── Popover ── */
.ext-popover-content {
  position: relative;
  background: var(--popover);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.15);
  color: var(--popover-foreground);
  animation: ext-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

/* ── Separator ── */
.ext-separator {
  flex-shrink: 0;
  background: var(--border);
}

.ext-separator--horizontal {
  height: 1px;
  margin: 0.25rem 0;
}

.ext-separator--vertical {
  width: 1px;
  height: 1rem;
  align-self: center;
  margin: 0 0.25rem;
}

/* ── Input ── */
.ext-input {
  width: 100%;
  height: 2rem;
  padding: 0 0.625rem;
  border: 1px solid var(--border);
  border-radius: calc(var(--radius) - 2px);
  background: var(--background);
  color: var(--foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  outline: none;
  transition:
    border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}

.ext-input::placeholder {
  color: var(--muted-foreground);
}

.ext-input:focus-visible {
  border-color: var(--ring);
  box-shadow: 0 0 0 2px color-mix(in srgb, var(--ring) 30%, transparent);
}

/* ── Tabs ── */
.ext-tabs {
  display: flex;
  flex-direction: column;
}

.ext-tabs-list {
  display: flex;
  gap: 0.125rem;
  width: fit-content;
  padding: 0.25rem;
  border-radius: calc(var(--radius) - 4px);
  background: var(--muted);
}

.ext-tabs-trigger {
  display: inline-flex;
  align-items: center;
  gap: 0.375rem;
  padding: 0.25rem 0.625rem;
  border: none;
  border-radius: calc(var(--radius) - 6px);
  background: transparent;
  color: var(--muted-foreground);
  font-size: 0.8125rem;
  font-family: inherit;
  white-space: nowrap;
  cursor: pointer;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out;
}

.ext-tabs-trigger > svg {
  width: 1rem;
  height: 1rem;
  flex-shrink: 0;
}

.ext-tabs-trigger:hover,
.ext-tabs-trigger:focus-visible {
  color: var(--foreground);
  outline: none;
}

.ext-tabs-trigger--active {
  background: var(--background);
  color: var(--foreground);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);
}

.ext-tabs-content {
  padding-top: 0.5rem;
}
